import argparse

from uploader import upload


class Client:
    def put(self, path):
        return "remote-" + path


def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument("files", nargs="+")
    args = parser.parse_args(argv)
    client = Client()
    for name in args.files:
        upload(client, name)


if __name__ == "__main__":
    main()

