import unittest

from uploader import UploadError, upload


class FakeClient:
    def __init__(self, fail):
        self.fail = fail
        self.calls = 0

    def put(self, path):
        self.calls += 1
        if self.fail:
            raise ConnectionError("down")
        return "id-1"


class UploadTests(unittest.TestCase):
    def test_success(self):
        client = FakeClient(fail=False)
        self.assertEqual(upload(client, "a.txt"), "id-1")

    def test_failure_is_reported_after_one_attempt(self):
        client = FakeClient(fail=True)
        with self.assertRaises(UploadError):
            upload(client, "a.txt")
        self.assertEqual(client.calls, 1)


if __name__ == "__main__":
    unittest.main()

